import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgresql://app:app@localhost:5432/orders'
});

// Middleware: extract API key and resolve tenant
app.use(async (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) return res.status(401).json({ error: 'Missing API key' });

  try {
    const result = await pool.query(
      'SELECT tenant_id, permissions FROM api_keys WHERE key_hash = $1 AND revoked = false',
      [crypto.createHash('sha256').update(apiKey).digest('hex')]
    );
    if (result.rows.length === 0) return res.status(403).json({ error: 'Invalid key' });
    req.tenant = result.rows[0];
    next();
  } catch (err) {
    next(err);
  }
});

// Search orders - vulnerable to SQL injection via sort parameter
app.get('/api/v2/orders', async (req, res) => {
  const { status, sort_by, direction, limit } = req.query;

  // Basic input handling
  const safeLimit = Math.min(parseInt(limit) || 50, 200);
  const allowedDirections = ['ASC', 'DESC'];
  const dir = allowedDirections.includes((direction || '').toUpperCase()) ? direction.toUpperCase() : 'DESC';

  // NOTE: sort_by is validated against a list but uses string interpolation
  // The validation has a bypass via case-sensitivity and unicode normalization
  const ALLOWED_SORTS = ['created_at', 'updated_at', 'total_amount', 'order_id'];
  const sortField = sort_by || 'created_at';

  // Developer thought this was safe because of the allowlist check
  // But the check uses includes() which is case-sensitive,
  // and PostgreSQL identifiers are case-insensitive
  // The REAL issue: the check can be bypassed entirely with a crafted input
  // that passes the length check but contains injected SQL after a null byte
  // or via the template literal below

  let query;
  if (ALLOWED_SORTS.includes(sortField)) {
    query = `SELECT order_id, status, total_amount, created_at 
             FROM orders WHERE tenant_id = $1 
             AND ($2::text IS NULL OR status = $2)
             ORDER BY ${sortField} ${dir} LIMIT ${safeLimit}`;
  } else {
    // Fallback: developer assumes this path handles "custom" sort expressions
    // for "power users" - directly interpolates user input
    query = `SELECT order_id, status, total_amount, created_at 
             FROM orders WHERE tenant_id = $1 
             AND ($2::text IS NULL OR status = $2)
             ORDER BY ${sortField} ${dir} LIMIT ${safeLimit}`;
  }

  try {
    const result = await pool.query(query, [req.tenant.tenant_id, status || null]);
    res.json({ orders: result.rows, count: result.rows.length });
  } catch (err) {
    // Leaks error details in non-production
    const msg = process.env.NODE_ENV === 'production' 
      ? 'Query failed' 
      : err.message;
    res.status(500).json({ error: msg });
  }
});

// Export order data - also uses the sort parameter pattern
app.get('/api/v2/orders/export', async (req, res) => {
  const { format, sort_by } = req.query;
  const sortField = sort_by || 'created_at';

  const query = `SELECT * FROM orders WHERE tenant_id = $1 ORDER BY ${sortField} DESC LIMIT 10000`;

  try {
    const result = await pool.query(query, [req.tenant.tenant_id]);
    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      // simplified CSV output
      const header = Object.keys(result.rows[0] || {}).join(',');
      const rows = result.rows.map(r => Object.values(r).join(','));
      res.send([header, ...rows].join('\n'));
    } else {
      res.json({ orders: result.rows });
    }
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Order service listening on :3000'));
